    "codeSnippet": "# GitHub Actions CI/CD workflow for: Pull Request Quality Gates & Automated Status Checks\nname: Automated Quality Gate - Pull Request Quality Gates & Automated Status Checks\non:\n  pull_request:\n    branches: [ main, develop ]\n\njobs:\n  test-quality-gate:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Setup Environment\n        uses: actions/setup-node@v4\n        with:\n          node-version: 20\n          cache: 'npm'\n      - run: npm ci\n      - name: Run Test Suite\n        run: npx playwright test --shard=1/2",
    "bestPractice": "Always isolate test dependencies, enforce deterministic assertions, and use clear semantic locators/endpoints to keep pull request quality gates & automated status checks resilient against flaky test runs.",
    "pitfallToAvoid": "Never use hardcoded Thread.sleep() or static shared mutable state across parallel test threads when testing pull request quality gates & automated status checks.",
